        <tbody>
          @for (r of items(); track r['id']) {
            <tr>
              <td>{{ r['ruleCode'] }}</td><td>{{ r['ruleName'] }}</td>
              <td>{{ r['ruleType'] }}</td><td>{{ r['action'] }}</td><td>{{ r['isActive'] }}</td>
            </tr>
          }
        </tbody>
      </table>
    }
  `,
})

